const fs=require('fs'),crypto=require('crypto'),assert=require('assert/strict');const before=JSON.parse(fs.readFileSync('releases/v281/manifest.json')),after=JSON.parse(fs.readFileSync('releases/v282/manifest.json'));const allowed=['app.html','provenance.json','lts-v183-v168-feedback-safe.js','lts-v179-cash-recovery.js'];assert.deepEqual(Object.keys(before.files).sort(),Object.keys(after.files).sort());for(const[n,h]of Object.entries(before.files))if(!allowed.includes(n))assert.equal(after.files[n],h,n);for(const[n,h]of Object.entries(after.files))assert.equal(crypto.createHash('sha256').update(fs.readFileSync('releases/v282/'+n)).digest('hex'),h,n);for(const[n,h]of Object.entries(after.protected))assert.equal(crypto.createHash('sha256').update(fs.readFileSync(n)).digest('hex'),h,n);assert(fs.readFileSync('releases/v281/index.html').equals(fs.readFileSync('releases/v282/index.html')));console.log('Reviewed two-asset scope and protected release hashes verified');